-- Reference data, part 3: wheat diseases (codes from ml/classes.yaml).
-- The same caveats as in V7 apply: Kazakh texts and treatments are drafts that
-- need a native speaker and an agrochemist; dosage is "per the product label".

INSERT INTO diseases (code, crop_code, kind, severity, latin_name, names, symptoms, conditions, prevention) VALUES
    ('wheat__leaf_rust', 'wheat', 'fungal', 'high', 'Puccinia triticina',
     '{"ru": "Бурая ржавчина", "kk": "Қоңыр тат", "en": "Leaf rust"}',
     '{"ru": ["Мелкие круглые оранжево-бурые пустулы, разбросанные по листовой пластинке", "Пустулы преимущественно на верхней стороне листа", "Листья желтеют и преждевременно засыхают, зерно щуплое"],
       "kk": ["Жапырақ тақтасына шашыраған ұсақ дөңгелек сарғыш-қоңыр пустулалар", "Пустулалар негізінен жапырақтың үстіңгі жағында", "Жапырақтар сарғайып, мезгілсіз кеуіп қалады, дән арық болады"],
       "en": ["Small round orange-brown pustules scattered over the leaf blade", "Pustules mostly on the upper side of the leaf", "Leaves yellow and die early, grain is shrivelled"]}',
     '{"ru": ["Температура 15–25 °C и длительная роса", "Тёплая влажная весна и начало лета", "Самосевы озимой пшеницы как резервация инфекции"],
       "kk": ["15–25 °C температура және ұзақ шық", "Жылы ылғалды көктем мен жаз басы", "Инфекция қоры ретінде күздік бидайдың өздігінен шыққан өскіндері"],
       "en": ["Temperature of 15–25 °C and long dew periods", "Warm, humid spring and early summer", "Volunteer winter wheat keeping the infection over"]}',
     '{"ru": ["Возделывать устойчивые сорта", "Уничтожать самосевы", "Соблюдать оптимальные сроки сева", "Мониторить посевы с фазы кущения"],
       "kk": ["Төзімді сорттарды өсіру", "Өздігінен шыққан өскіндерді жою", "Оңтайлы себу мерзімін сақтау", "Жапырақтану кезеңінен бастап егістерді бақылау"],
       "en": ["Grow resistant varieties", "Destroy volunteer plants", "Sow within the optimal window", "Scout fields from the tillering stage"]}'),

    ('wheat__stripe_rust', 'wheat', 'fungal', 'high', 'Puccinia striiformis',
     '{"ru": "Жёлтая ржавчина", "kk": "Сары тат", "en": "Stripe rust"}',
     '{"ru": ["Жёлтые пустулы, выстроенные в полосы вдоль жилок листа", "Жёлтый порошок спор остаётся на пальцах", "Сильное поражение резко снижает урожай и вес зерна"],
       "kk": ["Жапырақ тамырлары бойымен жолақ болып орналасқан сары пустулалар", "Саусақта сары спора ұнтағы қалады", "Қатты зақымдану өнім мен дән салмағын күрт азайтады"],
       "en": ["Yellow pustules arranged in stripes along the leaf veins", "Yellow spore powder comes off on fingers", "Severe infection sharply cuts yield and grain weight"]}',
     '{"ru": ["Прохладная влажная погода (10–15 °C) и росы", "Мягкая зима, при которой возбудитель переживает на озимых", "Восприимчивые сорта"],
       "kk": ["Салқын ылғалды ауа райы (10–15 °C) және шық", "Қоздырғыш күздік дақылдарда сақталатын жұмсақ қыс", "Бейім сорттар"],
       "en": ["Cool, humid weather (10–15 °C) and dew", "Mild winters that let the pathogen survive on winter wheat", "Susceptible varieties"]}',
     '{"ru": ["Устойчивые сорта и их чередование", "Уничтожать самосевы и зелёный мост", "Ранний мониторинг весной", "Сев в рекомендованные сроки"],
       "kk": ["Төзімді сорттар және оларды кезектестіру", "Өздігінен шыққан өскіндер мен жасыл көпірді жою", "Көктемде ерте бақылау", "Ұсынылған мерзімде себу"],
       "en": ["Resistant varieties, rotated over time", "Destroy volunteers and the green bridge", "Scout early in spring", "Sow within the recommended window"]}'),

    ('wheat__septoria', 'wheat', 'fungal', 'medium', 'Zymoseptoria tritici',
     '{"ru": "Септориоз", "kk": "Септориоз", "en": "Septoria"}',
     '{"ru": ["Вытянутые светло-бурые пятна с жёлтой каймой на листьях", "В пятнах видны мелкие чёрные точки — плодовые тела гриба", "Пятна сливаются, лист засыхает снизу вверх"],
       "kk": ["Жапырақтарда сары жиегі бар ұзынша ақшыл қоңыр дақтар", "Дақтарда ұсақ қара нүктелер — саңырауқұлақтың жеміс денелері көрінеді", "Дақтар қосылып, жапырақ төменнен жоғары қарай кебеді"],
       "en": ["Elongated pale brown lesions with a yellow border on leaves", "Tiny black dots — fungal fruiting bodies — visible in the lesions", "Lesions merge and the leaf dies from the bottom upward"]}',
     '{"ru": ["Влажная погода с частыми дождями", "Остатки заражённой соломы и стерни", "Загущенные посевы"],
       "kk": ["Жиі жаңбырлы ылғалды ауа райы", "Залалданған сабан мен тарлан қалдықтары", "Қалың егістер"],
       "en": ["Wet weather with frequent rain", "Infected straw and stubble", "Dense crops"]}',
     '{"ru": ["Севооборот и заделка пожнивных остатков", "Устойчивые сорта", "Обеззараживание семян", "Не загущать посевы"],
       "kk": ["Ауыспалы егіс және оруданкейінгі қалдықтарды көму", "Төзімді сорттар", "Тұқымды залалсыздандыру", "Егістерді қалың себпеу"],
       "en": ["Rotate crops and bury stubble", "Resistant varieties", "Seed treatment", "Avoid dense sowing"]}'),

    ('wheat__powdery_mildew', 'wheat', 'fungal', 'medium', 'Blumeria graminis f. sp. tritici',
     '{"ru": "Мучнистая роса", "kk": "Ақ ұнтақ", "en": "Powdery mildew"}',
     '{"ru": ["Белый мучнистый налёт на листьях, стеблях и колосьях", "Налёт со временем сереет и покрывается чёрными точками", "Поражённые листья желтеют и засыхают"],
       "kk": ["Жапырақтарда, сабақтар мен масақтарда ақ ұнтақты жабын", "Жабын уақыт өте сұрланып, қара нүктелермен жабылады", "Зақымданған жапырақтар сарғайып, кеуіп қалады"],
       "en": ["White powdery coating on leaves, stems and ears", "The coating turns grey and develops black dots with age", "Infected leaves turn yellow and dry"]}',
     '{"ru": ["Прохладная погода с высокой влажностью воздуха без обильных дождей", "Густые посевы и избыток азота", "Восприимчивые сорта"],
       "kk": ["Мол жаңбырсыз ауаның жоғары ылғалдылығы бар салқын ауа райы", "Қалың егістер және азоттың артық болуы", "Бейім сорттар"],
       "en": ["Cool weather with high air humidity but little heavy rain", "Dense crops and excess nitrogen", "Susceptible varieties"]}',
     '{"ru": ["Устойчивые сорта", "Не передозировать азотные удобрения", "Оптимальная норма высева", "Уничтожение самосевов и стерни"],
       "kk": ["Төзімді сорттар", "Азот тыңайтқыштарын шамадан тыс бермеу", "Оңтайлы себу нормасы", "Өздігінен шыққан өскіндер мен тарланды жою"],
       "en": ["Resistant varieties", "Do not overapply nitrogen", "Use the optimal seeding rate", "Destroy volunteers and stubble"]}'),

    ('wheat__healthy', 'wheat', 'healthy', NULL, NULL,
     '{"ru": "Здоровое растение", "kk": "Сау өсімдік", "en": "Healthy"}',
     '{"ru": ["Признаков болезни не обнаружено"], "kk": ["Аурудың белгісі табылмады"], "en": ["No signs of disease found"]}',
