       "en": ["Scout fields regularly", "Rotate crops and choose resistant varieties"]}');

INSERT INTO treatments (disease_code, type, product, active_ingredient, dosage, method, sort_order) VALUES
    ('wheat__leaf_rust', 'chemical', 'Тебуконазол', 'tebuconazole',
